command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: HYPNOTISCHER BLICK (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Hypnotischer Blick";
    const ahne = "brona"; 
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    // --- 3. TARGET ERMITTELN ---
    let targets = Array.from(game.user.targets);
    if (targets.length === 0 || targets.length > 1) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle genau EIN Ziel (Target) für den hypnotischen Blick!");
    }
    const targetActor = targets[0].actor;
    if (!targetActor) return;

    // --- 4. BERECHNUNGEN ---
    const dauerMinuten = qs;
    const dauerSekunden = dauerMinuten * 60;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    // --- 5. EFFEKTE ANWENDEN (Auf beide!) ---
    // A) Effekt für den Wirkenden (Konzentration)
    const casterEffektName = `${gabenName} (Brona) - Konzentration`; // 🚩 LUNAS FIX: Gruppierter Name
    let alterCasterEffekt = casterActor.effects.find(e => (e.name || e.label) === casterEffektName);
    if (alterCasterEffekt) await alterCasterEffekt.delete();

    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: casterEffektName,
        icon: iconBild,
        description: `Du hältst den hypnotischen Blick auf ${targetActor.name} gerichtet. Wird der Blick unterbrochen, endet die Wirkung sofort!`,
        duration: { seconds: dauerSekunden }
    }]);

    // B) Effekt für das Ziel (Hypnotisiert)
    const targetEffektName = `${gabenName} (Brona) - Opfer`; // 🚩 LUNAS FIX: Gruppierter Name
    let alterTargetEffekt = targetActor.effects.find(e => (e.name || e.label) === targetEffektName);
    if (alterTargetEffekt) await alterTargetEffekt.delete();

    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: targetEffektName,
        icon: iconBild,
        description: `Du hast dich in den Augen des Vampirs verloren. Du bist völlig reglos! (Starr)`,
        duration: { seconds: dauerSekunden },
        flags: { core: { statusId: "stunned" } } // Setzt das Foundry-Standard-Icon für "Betäubt"
    }]);

    // --- 6. FLAG-CLEANUP ---
    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    // --- 7. STRENG GEHEIME CHAT-KARTE BAUEN ---
    let whisperIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(targetActor).forEach(id => whisperIds.add(id)); // Geht NUR an das Ziel und den GM!
    getOwners(casterActor).forEach(id => whisperIds.add(id)); // Und an den Caster

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header("Heimliche Hypnose", iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px; text-align: center;"><b>${casterActor.name}</b> blickt <b>${targetActor.name}</b> tief in die Augen...</p>

                <div style="padding: 10px; margin: 10px 0; border: 1px dashed #76301b; background: rgba(118, 48, 27, 0.05);">
                    <p style="color: #76301b; font-weight: bold; margin-top: 0; margin-bottom: 8px; text-align: center; font-size: 1.1em; letter-spacing: 1px;">
                        — STRENG GEHEIM —
                    </p>
                    <p style="margin-bottom: 8px; text-align: justify; color: #000; font-size: 0.95em;">
                        <b>An den Spieler von ${targetActor.name}:</b> Du hast dich in den Augen des Vampirs verloren und bleibst ab sofort völlig reglos stehen.
                    </p>
                    <p style="margin-bottom: 0; text-align: justify; color: #76301b; font-weight: bold; font-size: 0.95em;">
                        Verrate deinen Mitspielern NICHT, warum du plötzlich eingefroren bist. Spiele es einfach aus und lass sie selbst herausfinden, was passiert ist!
                    </p>
                </div>

                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                    Wirkungsdauer:<br>${dauerMinuten} Minuten <span ${thinStyle}>(QS ${qs})</span>
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent, whisper: Array.from(whisperIds) });
    } else {
        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(whisperIds).filter(id => game.users.get(id)),
            content: cardContent
        });
    }
})();
